   126→      : {}),
   127→  };
   128→};
   129→
   130→export const buildGateResult = (
   131→  evaluatedRules: EvaluatedRule[],
   132→  denyMatched: boolean,
   133→  warnings: PolicyGateWarning[],
   134→  evidenceRequirements?: PolicyEvidenceRequirements,
   135→): PolicyGateResult => {
   136→  const policyTrace: PolicyTraceEntry[] = evaluatedRules.map((entry) => ({
   137→    policy_id: entry.policyId,
   138→    policy_version: entry.policyVersion,
   139→    rule_id: entry.rule.id,
   140→    effect: entry.rule.effect,
   141→    matched: entry.matched,
   142→    priority: entry.rule.priority,
   143→  }));
   144→
   145→  if (denyMatched) {
   146→    const denyRule = evaluatedRules.find(
   147→      (entry) => entry.matched && entry.rule.effect === "deny",
   148→    );
   149→    return {
   150→      passed: false,
   151→      reason: `Policy deny rule '${denyRule!.rule.id}' matched`,
   152→      policy_trace: policyTrace,
   153→      deny_rule_id: denyRule!.rule.id,
   154→      warnings,
   155→    };
   156→  }
   157→
   158→  const humanVetoRequired = evaluatedRules.some(
   159→    (entry) => entry.humanVetoRequired,
   160→  );
   161→
   162→  return {
   163→    passed: true,
   164→    policy_trace: policyTrace,
   165→    human_veto_required: humanVetoRequired,
   166→    warnings,
   167→    ...(evidenceRequirements ? { evidence_requirements: evidenceRequirements } : {}),
   168→  };
   169→};
   170→
   171→// ---------------------------------------------------------------------------
   172→// Composition Root (single effect boundary)
   173→// ---------------------------------------------------------------------------
   174→
   175→export const evaluatePolicyGate = async (
   176→  surreal: Surreal,
   177→  identityId: RecordId<"identity">,
   178→  workspaceId: RecordId<"workspace">,
   179→  intentContext: IntentEvaluationContext,
   180→): Promise<PolicyGateResult> => {
   181→  // Effect boundary: single DB read
   182→  const rawPolicies = await loadActivePolicies(surreal, identityId, workspaceId);
   183→
   184→  // Pure pipeline
   185→  const deduplicated = deduplicatePolicies(rawPolicies);
   186→  const sortedRules = collectAndSortRules(deduplicated);
   187→  const { evaluatedRules, denyMatched, warnings } = evaluateRulesAgainstContext(
   188→    sortedRules,
   189→    intentContext,
   190→  );
   191→  const evidenceRequirements = extractEvidenceRequirements(evaluatedRules);
   192→
   193→  return buildGateResult(evaluatedRules, denyMatched, warnings, evidenceRequirements);
   194→};
