   178→export async function getPolicyRecord(
   179→  surreal: Surreal,
   180→  policyId: string,
   181→): Promise<PolicyRecord> {
   182→  const policyRecord = new RecordId("policy", policyId);
   183→  const rows = (await surreal.query(`SELECT * FROM $policy;`, {
   184→    policy: policyRecord,
   185→  })) as Array<Array<PolicyRecord>>;
   186→  const result = rows[0]?.[0];
   187→  if (!result) throw new Error(`Policy ${policyId} not found`);
   188→  return result;
