   200→  const identityPolicies = (await surreal.query(
   201→    `SELECT ->governing->policy.* AS policies FROM $identity;`,
   202→    { identity: identityRecord },
   203→  )) as Array<Array<{ policies: PolicyRecord[] }>>;
   204→
   205→  // Workspace-linked policies
   206→  const workspacePolicies = (await surreal.query(
   207→    `SELECT <-protects<-policy.* AS policies FROM $workspace;`,
   208→    { workspace: workspaceRecord },
   209→  )) as Array<Array<{ policies: PolicyRecord[] }>>;
   210→
   211→  const idPolicies = identityPolicies[0]?.[0]?.policies ?? [];
   212→  const wsPolicies = workspacePolicies[0]?.[0]?.policies ?? [];
   213→
   214→  // Deduplicate by policy ID and filter active only
   215→  const seen = new Set<string>();
   216→  const all: PolicyRecord[] = [];
   217→  for (const p of [...idPolicies, ...wsPolicies]) {
   218→    const id = p.id.id as string;
   219→    if (!seen.has(id) && p.status === "active") {
   220→      seen.add(id);
   221→      all.push(p);
   222→    }
   223→  }
   224→  return all;
   225→}
