     1→/**
     2→ * Regorus WASM loader and Rego compilation interface.
     3→ *
     4→ * WASM loading strategy:
     5→ * - Synchronous CJS require() via wasm-bindgen nodejs target
     6→ * - Module-level promise for idempotent lazy init (safe for concurrent calls)
     7→ * - Fail-closed: WASM load failure throws; callers catch to return deny
     8→ */
     9→
    10→import type { IntentEvaluationContext } from "./types";
    11→
    12→export type CompileError = {
    13→  line: number;
    14→  column: number;
    15→  message: string;
    16→};
    17→
    18→export type CompileResult =
    19→  | { success: true }
    20→  | { success: false; errors: CompileError[] };
    21→
    22→export type RegoEvaluationResult = {
    23→  decision: "allow" | "deny";
    24→  messages: string[];
    25→  evidence_requirement?: { min_count: number; required_types?: string[] };
    26→};
    27→
    28→// ---------------------------------------------------------------------------
    29→// WASM module type (subset of Regorus JS bindings)
    30→// ---------------------------------------------------------------------------
    31→
    32→type RegorusModule = {
    33→  Engine: new () => RegorusEngine;
    34→};
    35→
    36→type RegorusEngine = {
    37→  addPolicy(path: string, rego: string): string;
    38→  setInputJson(input: string): void;
    39→  evalQuery(query: string): string;
    40→  getPackages(): string[];
    41→  free(): void;
    42→};
    43→
    44→// ---------------------------------------------------------------------------
    45→// evalQuery result shape
    46→// ---------------------------------------------------------------------------
    47→
    48→type EvalQueryResult = {
    49→  result?: Array<{
    50→    expressions: Array<{
    51→      value: unknown;
    52→    }>;
    53→  }>;
    54→};
    55→
    56→// ---------------------------------------------------------------------------
    57→// Module-level idempotent WASM init promise
    58→// Prohibited: module-level mutable singletons (AGENTS.md)
    59→// Allowed: module-level promise is idempotent — concurrent calls share the
    60→// same promise and all await the same result.
    61→// ---------------------------------------------------------------------------
    62→
    63→const regorusModulePromise: Promise<RegorusModule> = (async () => {
    64→  // require() is synchronous; wrapped in promise for uniform async interface
    65→  // eslint-disable-next-line @typescript-eslint/no-require-imports
    66→  const mod = require("../../../../vendor/regorus-wasm/regorusjs") as RegorusModule;
    67→  if (typeof mod.Engine !== "function") {
    68→    throw new Error("Regorus WASM failed to load: Engine class not found");
    69→  }
    70→  return mod;
    71→})();
    72→
    73→// ---------------------------------------------------------------------------
    74→// Error parsing
    75→// ---------------------------------------------------------------------------
    76→
    77→/**
    78→ * Parse the Regorus error string format into structured CompileError objects.
    79→ *
    80→ * Format example:
    81→ *   \n--> test.rego:2:18\n  |\n2 | default allow := !!!\n  |  ^\nerror: invalid character
    82→ *
    83→ * The location header pattern: `--> <file>:<line>:<column>`
    84→ * The error message follows on the last line: `error: <message>`
    85→ */
    86→const parseRegorusErrorString = (errorString: string): CompileError[] => {
    87→  const lines = errorString.split("\n");
    88→  const errors: CompileError[] = [];
    89→
    90→  let currentLine: number | undefined;
    91→  let currentColumn: number | undefined;
    92→
    93→  for (const line of lines) {
    94→    const locationMatch = line.match(/^-->\s+\S+:(\d+):(\d+)\s*$/);
    95→    if (locationMatch) {
    96→      currentLine = parseInt(locationMatch[1], 10);
    97→      currentColumn = parseInt(locationMatch[2], 10);
    98→      continue;
    99→    }
   100→
   101→    const errorMessageMatch = line.match(/^error:\s+(.+)$/);
   102→    if (errorMessageMatch) {
   103→      errors.push({
   104→        line: currentLine ?? 0,
   105→        column: currentColumn ?? 0,
   106→        message: errorMessageMatch[1].trim(),
   107→      });
   108→      currentLine = undefined;
   109→      currentColumn = undefined;
   110→    }
   111→  }
   112→
   113→  if (errors.length === 0 && errorString.trim().length > 0) {
   114→    // Fallback: return the raw error as a single entry without location
   115→    errors.push({ line: 0, column: 0, message: errorString.trim() });
   116→  }
   117→
   118→  return errors;
   119→};
   120→
   121→// ---------------------------------------------------------------------------
   122→// evalQuery helpers
   123→// ---------------------------------------------------------------------------
   124→
   125→const extractQueryValue = (queryResultJson: string): unknown => {
   126→  const parsed = JSON.parse(queryResultJson) as EvalQueryResult;
   127→  if (
   128→    !parsed.result ||
   129→    parsed.result.length === 0 ||
   130→    !parsed.result[0].expressions ||
   131→    parsed.result[0].expressions.length === 0
   132→  ) {
   133→    return undefined;
   134→  }
   135→  return parsed.result[0].expressions[0].value;
   136→};
   137→
   138→const extractAllowValue = (engine: RegorusEngine): boolean => {
   139→  const raw = engine.evalQuery("data.osabio.policy.allow");
   140→  const value = extractQueryValue(raw);
   141→  return value === true;
   142→};
   143→
   144→const extractDenyMessages = (engine: RegorusEngine): string[] => {
   145→  const raw = engine.evalQuery("data.osabio.policy.deny");
   146→  const value = extractQueryValue(raw);
   147→  if (!Array.isArray(value)) {
   148→    return [];
   149→  }
   150→  return value.filter((msg): msg is string => typeof msg === "string");
   151→};
   152→
   153→const extractEvidenceRequirement = (
   154→  engine: RegorusEngine,
   155→): RegoEvaluationResult["evidence_requirement"] => {
   156→  const raw = engine.evalQuery("data.osabio.policy.evidence_requirement");
   157→  const value = extractQueryValue(raw);
   158→
   159→  if (value === undefined || value === null || typeof value !== "object") {
   160→    return undefined;
   161→  }
   162→
   163→  const candidate = value as Record<string, unknown>;
   164→
   165→  if (typeof candidate.min_count !== "number") {
   166→    console.warn(
   167→      "[rego-evaluator] evidence_requirement.min_count is not a number — treating as no requirement",
   168→      candidate,
   169→    );
   170→    return undefined;
   171→  }
   172→
   173→  const requiredTypes =
   174→    Array.isArray(candidate.required_types) &&
   175→    candidate.required_types.every((t) => typeof t === "string")
   176→      ? (candidate.required_types as string[])
   177→      : undefined;
   178→
   179→  if (
   180→    candidate.required_types !== undefined &&
   181→    requiredTypes === undefined
   182→  ) {
   183→    console.warn(
   184→      "[rego-evaluator] evidence_requirement.required_types contains non-string entries — ignoring field",
   185→      candidate.required_types,
   186→    );
   187→  }
   188→
   189→  return { min_count: candidate.min_count, required_types: requiredTypes };
   190→};
   191→
   192→// ---------------------------------------------------------------------------
   193→// Decision logic (fail-closed)
   194→// ---------------------------------------------------------------------------
   195→
   196→const buildDecision = (
   197→  allowValue: boolean,
   198→  denyMessages: string[],
   199→  evidenceRequirement: RegoEvaluationResult["evidence_requirement"],
   200→): RegoEvaluationResult => {
   201→  if (denyMessages.length > 0) {
   202→    return { decision: "deny", messages: denyMessages };
   203→  }
   204→  if (allowValue) {
   205→    return {
   206→      decision: "allow",
   207→      messages: [],
   208→      evidence_requirement: evidenceRequirement,
   209→    };
   210→  }
   211→  // Fail-closed: neither allow=true nor deny messages
   212→  return { decision: "deny", messages: ["policy produced no decision"] };
   213→};
   214→
   215→// ---------------------------------------------------------------------------
   216→// Package validation
   217→// ---------------------------------------------------------------------------
   218→
   219→const REQUIRED_PACKAGE = "data.osabio.policy";
   220→
   221→const validatePackage = (engine: RegorusEngine): void => {
   222→  const packages = engine.getPackages();
   223→  if (!packages.includes(REQUIRED_PACKAGE)) {
   224→    throw new Error("policy must declare package osabio.policy");
   225→  }
   226→};
   227→
   228→// ---------------------------------------------------------------------------
   229→// Engine cache factory
   230→// ---------------------------------------------------------------------------
   231→
   232→/**
   233→ * Create a new engine cache.
   234→ *
   235→ * The cache is keyed by "${policyId}:${version}" and stores pre-loaded Engine
   236→ * instances. Pass the cache as a parameter to evaluateRegoPolicy — this avoids
   237→ * module-level mutable state (AGENTS.md).
   238→ */
   239→export const createEngineCache = (): Map<string, RegorusEngine> =>
   240→  new Map<string, RegorusEngine>();
   241→
   242→// ---------------------------------------------------------------------------
   243→// Public API
   244→// ---------------------------------------------------------------------------
   245→
   246→/**
   247→ * Compile a Rego source string using Regorus.
   248→ *
   249→ * Returns { success: true } when the policy parses without errors.
   250→ * Returns { success: false; errors } with structured error locations otherwise.
   251→ *
   252→ * Throws only if the WASM module itself failed to load (fail-closed).
   253→ */
   254→export const compileRego = async (source: string): Promise<CompileResult> => {
   255→  const regorus = await regorusModulePromise;
   256→  const engine = new regorus.Engine();
   257→
   258→  try {
   259→    engine.addPolicy("policy.rego", source);
   260→    return { success: true };
   261→  } catch (err: unknown) {
   262→    const errorString = typeof err === "string" ? err : String(err);
   263→    const errors = parseRegorusErrorString(errorString);
   264→    return { success: false, errors };
   265→  } finally {
   266→    engine.free();
   267→  }
   268→};
   269→
   270→/**
   271→ * Evaluate a Rego policy against the given intent evaluation context.
   272→ *
   273→ * Queries data.osabio.policy.allow, data.osabio.policy.deny, and
   274→ * data.osabio.policy.evidence_requirement from the compiled engine.
   275→ *
   276→ * Decision logic (fail-closed):
   277→ * - deny set non-empty → decision: "deny", messages from deny set
   278→ * - allow=true, deny empty → decision: "allow"
   279→ * - allow=false, deny empty → decision: "deny", messages: ["policy produced no decision"]
   280→ *
   281→ * The engine is cached by "${policyId}:${version}" — pass the same cache
   282→ * across calls to reuse compiled engines for the same policy version.
   283→ *
   284→ * Throws if:
   285→ * - WASM module failed to load
   286→ * - Rego source does not declare package osabio.policy
   287→ */
   288→export const evaluateRegoPolicy = async (
   289→  regoSource: string,
   290→  policyId: string,
   291→  version: number,
   292→  context: IntentEvaluationContext,
   293→  cache: Map<string, RegorusEngine>,
   294→): Promise<RegoEvaluationResult> => {
   295→  const regorus = await regorusModulePromise;
   296→  const cacheKey = `${policyId}:${version}`;
   297→
   298→  let engine = cache.get(cacheKey);
   299→
   300→  if (!engine) {
   301→    engine = new regorus.Engine();
   302→    engine.addPolicy("policy.rego", regoSource);
   303→    validatePackage(engine);
   304→    cache.set(cacheKey, engine);
   305→  }
   306→
   307→  engine.setInputJson(JSON.stringify(context));
   308→
   309→  const allowValue = extractAllowValue(engine);
   310→  const denyMessages = extractDenyMessages(engine);
   311→  const evidenceRequirement = extractEvidenceRequirement(engine);
   312→
   313→  return buildDecision(allowValue, denyMessages, evidenceRequirement);
   314→};
